}

-- Native range preview: drawn while the item is held in the cursor and while the entity is selected, so the
-- circle is visible *before* placing and when clicking a built one (the engine scales the sprite to `distance`).
local function ring(entity, distance, colour)
  entity.radius_visualisation_specification = {
    sprite = {filename = G .. "radius-" .. colour .. ".png", size = 512},
    distance = distance,
  }
end
ring(hall, 64, "green")             -- territory.HALL_RADIUS
ring(watchtower, 48, "green")       -- territory.TOWER_RADIUS
for _, hut in ipairs{forager, woodcutter, miner, farmhut, huntinglodge, fishingdock, smokehouse, kitchen} do
  ring(hut, 48, "yellow")           -- colony.HUT_RADIUS
end

